/**
 * Phase 4A.2: Real Redis + BullMQ Integration Test Suite
 *
 * Opt-In Integration Test:
 * This test only executes against a live Redis/Valkey service when explicitly enabled:
 *   RUN_REDIS_INTEGRATION_TESTS=1 node --test tests/bullmq.real.redis.integration.test.js
 *
 * Prerequisites for running this test:
 *   1. Start local Redis test container:
 *      docker compose -f docker-compose.test-redis.yml up -d
 *   2. Or start a local Redis / Valkey server listening on 127.0.0.1:6379.
 *
 * Verifies:
 *   1. Colon-free job IDs generated by generateMediaCleanupJobId() are accepted by real BullMQ.
 *   2. Submitted jobs are dispatched to real Redis and processed by a real BullMQ Worker.
 *   3. Duplicate job submissions with the same custom jobId are deduplicated by BullMQ.
 *   4. Clean shutdown of real Worker and Queue connections.
 *   5. Redis unavailability does not hang the cleanup producer path indefinitely.
 *
 * SAFETY INVARIANTS:
 *   - Never connects to production Redis or MongoDB.
 *   - Uses an isolated, unique test queue name per run.
 *   - Does not delete real S3 media or modify user accounts.
 */

import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import Redis from "ioredis";
import { Queue, Worker } from "bullmq";

import {
    generateMediaCleanupJobId,
} from "../src/services/queue.service.js";
import {
    getProducerConnectionConfig,
    getWorkerConnectionConfig,
    DEFAULT_JOB_OPTIONS,
} from "../src/config/queue.js";
import { dispatchMediaCleanup } from "../src/services/storage.service.js";

const isIntegrationEnabled = process.env.RUN_REDIS_INTEGRATION_TESTS === "1";
const testRedisUrl = process.env.TEST_REDIS_URL || process.env.REDIS_URL || "redis://127.0.0.1:6379";

describe("Phase 4A.2: Real Redis + BullMQ Integration Suite (Opt-in)", () => {
    if (!isIntegrationEnabled) {
        it("Opt-in Real Redis Integration test is disabled by default", (t) => {
            t.skip(
                "Skipped: To run real Redis/Valkey integration tests, start local Redis via 'docker compose -f docker-compose.test-redis.yml up -d' and set RUN_REDIS_INTEGRATION_TESTS=1."
            );
        });
        return;
    }

    let redisProbeClient = null;
    let isLocalRedisReachable = false;
    let producerClient = null;
    let workerClient = null;
    let testQueue = null;
    let testWorker = null;

    const testPrefix = "engaze:test:bullmq";
    const testQueueName = `test-media-cleanup-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const processedJobs = [];

    before(async () => {
        // Probe if local Redis is actually responsive
        try {
            redisProbeClient = new Redis(testRedisUrl, {
                connectTimeout: 2000,
                maxRetriesPerRequest: 1,
                lazyConnect: true,
            });
            redisProbeClient.on("error", () => {});
            await redisProbeClient.connect();
            const pong = await redisProbeClient.ping();
            isLocalRedisReachable = pong === "PONG";
        } catch (probeErr) {
            isLocalRedisReachable = false;
            console.warn(`[IntegrationTest] Local Redis probe failed (${probeErr.message}). Tests will assert graceful degradation.`);
        }
    });

    after(async () => {
        if (testWorker) {
            try {
                await testWorker.close();
            } catch (_) {}
            testWorker = null;
        }

        if (testQueue) {
            try {
                // Drain and clean test queue keys
                await testQueue.drain();
                await testQueue.clean(0, 1000, "completed");
                await testQueue.clean(0, 1000, "failed");
                await testQueue.close();
            } catch (_) {}
            testQueue = null;
        }

        if (workerClient) {
            try {
                await workerClient.quit();
            } catch (_) {}
            workerClient = null;
        }

        if (producerClient) {
            try {
                await producerClient.quit();
            } catch (_) {}
            producerClient = null;
        }

        if (redisProbeClient) {
            try {
                await redisProbeClient.quit();
            } catch (_) {}
            redisProbeClient = null;
        }
    });

    it("Requirement 1: Generates a valid colon-free job ID that BullMQ Queue.add accepts", async (t) => {
        if (!isLocalRedisReachable) {
            t.skip("Local Redis server not reachable on " + testRedisUrl);
            return;
        }

        const producerOpts = getProducerConnectionConfig({ url: testRedisUrl, tls: false });
        const { url: pUrl, ...pRedisOpts } = producerOpts;
        producerClient = new Redis(pUrl, pRedisOpts);

        testQueue = new Queue(testQueueName, {
            connection: producerClient,
            prefix: testPrefix,
        });

        const testKey = "profile-photos/testuser1/avatar.webp";
        const testUserId = "testuser1";
        const customJobId = generateMediaCleanupJobId(testKey, testUserId);

        assert.ok(!customJobId.includes(":"), "Job ID must not contain colon character");
        assert.match(customJobId, /^media-cleanup-[0-9a-f]{64}$/);

        // Add job with real BullMQ to real Redis
        const job = await testQueue.add(
            "cleanup-object",
            { key: testKey, userId: testUserId },
            {
                jobId: customJobId,
                ...DEFAULT_JOB_OPTIONS,
            }
        );

        assert.ok(job);
        assert.equal(job.id, customJobId);
    });

    it("Requirement 2: Real BullMQ Worker picks up the job and processes it to completion", async (t) => {
        if (!isLocalRedisReachable || !testQueue) {
            t.skip("Local Redis server not reachable on " + testRedisUrl);
            return;
        }

        const workerOpts = getWorkerConnectionConfig({ url: testRedisUrl, tls: false });
        const { url: wUrl, ...wRedisOpts } = workerOpts;
        workerClient = new Redis(wUrl, wRedisOpts);

        let jobCompletedPromiseResolve;
        const jobCompletedPromise = new Promise((resolve) => {
            jobCompletedPromiseResolve = resolve;
        });

        testWorker = new Worker(
            testQueueName,
            async (job) => {
                processedJobs.push({ id: job.id, data: job.data });
                return { deleted: true, key: job.data.key };
            },
            {
                connection: workerClient,
                prefix: testPrefix,
                concurrency: 2,
            }
        );

        testWorker.on("completed", (job) => {
            jobCompletedPromiseResolve(job);
        });

        // Wait for job execution with a strict bounded timeout
        const completedJob = await Promise.race([
            jobCompletedPromise,
            new Promise((_, reject) =>
                setTimeout(() => reject(new Error("Worker processing timed out after 5000ms")), 5000)
            ),
        ]);

        assert.ok(completedJob);
        assert.equal(processedJobs.length, 1);
        assert.equal(processedJobs[0].data.key, "profile-photos/testuser1/avatar.webp");
    });

    it("Requirement 3: Submitting duplicate job with same custom jobId follows BullMQ deduplication", async (t) => {
        if (!isLocalRedisReachable || !testQueue) {
            t.skip("Local Redis server not reachable on " + testRedisUrl);
            return;
        }

        const testKey = "profile-photos/testuser1/avatar.webp";
        const testUserId = "testuser1";
        const customJobId = generateMediaCleanupJobId(testKey, testUserId);

        // BullMQ job retention keeps completed jobs (DEFAULT_JOB_OPTIONS.removeOnComplete)
        // Adding the same jobId while retained returns the existing job without re-queueing
        const duplicateJob = await testQueue.add(
            "cleanup-object",
            { key: testKey, userId: testUserId },
            {
                jobId: customJobId,
                ...DEFAULT_JOB_OPTIONS,
            }
        );

        assert.ok(duplicateJob);
        assert.equal(duplicateJob.id, customJobId);
        // Worker was not triggered a second time
        assert.equal(processedJobs.length, 1);
    });

    it("Requirement 4: Real Queue and Worker close cleanly without leaving orphan connections", async (t) => {
        if (!isLocalRedisReachable || !testWorker || !testQueue) {
            t.skip("Local Redis server not reachable on " + testRedisUrl);
            return;
        }

        await assert.doesNotReject(async () => {
            await testWorker.close();
            await testQueue.close();
            testWorker = null;
            testQueue = null;
        });
    });

    it("Requirement 5: Producer to unreachable Redis fails in bounded time and falls back inline without hanging", async () => {
        // Points to an unreachable loopback port to test bounded connection failure
        const deadRedisUrl = "redis://127.0.0.1:59999";
        const deadProducerOpts = getProducerConnectionConfig({ url: deadRedisUrl, tls: false });
        const { url: deadUrl, ...deadRedisOpts } = deadProducerOpts;

        const deadClient = new Redis(deadUrl, {
            ...deadRedisOpts,
            maxRetriesPerRequest: 1,
            connectTimeout: 800,
            commandTimeout: 800,
            retryStrategy: () => null, // Do not reconnect
        });

        const deadQueue = new Queue("dead-test-queue", {
            connection: deadClient,
            prefix: "engaze:dead",
        });

        // Suppress unhandled error log on the dead client
        deadClient.on("error", () => {});
        deadQueue.on("error", () => {});

        let fallbackExecuted = false;
        const mockAdapter = {
            deleteObject: async (k) => {
                fallbackExecuted = true;
                return true;
            },
        };

        const startTime = Date.now();

        // Verify that enqueue failure does not hang and triggers fallback
        try {
            await deadQueue.add("cleanup-object", { key: "k1", userId: "u1" }, {
                jobId: generateMediaCleanupJobId("k1", "u1"),
                attempts: 1,
            });
        } catch (enqueueErr) {
            // Expected bounded failure: falls back inline
            await mockAdapter.deleteObject("k1");
        }

        const elapsedMs = Date.now() - startTime;
        assert.ok(elapsedMs < 3000, `Expected producer failure within 3000ms, elapsed: ${elapsedMs}ms`);
        assert.equal(fallbackExecuted, true);

        try {
            await deadQueue.close();
            deadClient.disconnect();
        } catch (_) {}
    });
});
